            FType upper = getUpper(k);
            FType bound = upper == null ? FTypeTop.ONLY : upper;
            if (lower.subtypeOf(bound) && v.subtypeOf(bound)) {
                traceInstance("several", k, k, lower + " join " + v, bound, "");
                putPair(k, bound, bound);
